// Un solo item con el HTML del resumen (una fila por grupo).
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const filas = $input.all().map((i) => i.json);
const tabla = filas.length
  ? '<table border="1" cellpadding="6" cellspacing="0"><tr><th>Grupo</th><th>Estudiantes</th><th>Activos esta semana</th><th>Intentos</th><th>Aprobados</th><th>Éxito</th></tr>' +
    filas.map((f) => {
      const exito = Number(f.intentos_semana) ? Math.round((Number(f.aprobados_semana) / Number(f.intentos_semana)) * 100) + ' %' : '—';
      return `<tr><td>${esc(f.grupo)}</td><td>${f.estudiantes}</td><td>${f.activos_semana}</td><td>${f.intentos_semana}</td><td>${f.aprobados_semana}</td><td>${exito}</td></tr>`;
    }).join('') + '</table>'
  : '<p>No hay estudiantes activos registrados.</p>';
return [{ json: { html: '<p>Resumen de actividad de los últimos 7 días:</p>' + tabla + '<p>Detalle por estudiante en la sección Reportes de la plataforma.</p>' } }];
